-- =============================================================================
-- 438 — LE CAHIER D'EXERCICES DE TLE (partie 3)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/Tle/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 438 --niveau Tle --matieres grec,latin --suffixe 3 > supabase/contenu/438_exercices_tle_3.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   grec.k150               24 exercices · 8 chapitres
--   grec.k151               21 exercices · 7 chapitres
--   latin.k165              24 exercices · 8 chapitres
--   latin.k166              21 exercices · 7 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('c65f48da-c114-5d85-89c8-a369b5236880'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"La lame de plomb de Théagénès","competence":"analyser-document","situation":"Dans une tombe d’Athènes, des archéologues ont trouvé une lame de plomb roulée et percée d’un clou. Voici une tablette de ce genre, imaginée pour l’exercice : lis-la comme une archéologue.","documents":[{"id":"tablette","type":"texte","genre":"source","titre":"Tablette de défixion (καταδεσμός)","blocs":["Je lie la langue de Théagénès devant les juges de la cité.","Qu’il ne trouve plus ses mots, qu’il reste muet comme ce plomb !","Cette lame est roulée, percée d’un clou et déposée dans une tombe, près des morts."],"source":"Tablette imaginée pour l’exercice, d’après les tablettes de défixion grecques"}],"questions":[{"enonce":"Touche le mot qui dit ce que la magie fait à la langue de Théagénès.","aide":"Le mot grec καταδεσμός signifie « lien ».","type":"zone","document":"tablette","multiple":false},{"enonce":"Touche le métal dans lequel la lame est faite.","aide":"C’est un métal gris et mou, facile à graver.","type":"zone","document":"tablette","multiple":false},{"enonce":"Que cherche celui qui a fait graver cette tablette ?","aide":"Relis la première ligne : qui est visé, et où ?","type":"choix","options":[{"id":"a","texte":"Guérir Théagénès d’une maladie grave grâce à une formule"},{"id":"b","texte":"Empêcher son adversaire de parler efficacement devant le tribunal"},{"id":"c","texte":"Honorer les dieux de la cité par une offrande à tout le peuple"},{"id":"d","texte":"Faire revenir un amant qui a quitté la ville pendant la nuit"}],"multiple":false},{"enonce":"Relie chaque magicienne à ce qu’elle fait dans la littérature grecque.","aide":"Circé est chez Homère, Simaitha chez Théocrite, Médée chez Apollonios et Euripide.","type":"association","gauche":[{"id":"g0","texte":"Circé"},{"id":"g1","texte":"Simaitha"},{"id":"g2","texte":"Médée"}],"droite":[{"id":"d0","texte":"Fait tourner un iynx pour retrouver son amant"},{"id":"d1","texte":"Aide Jason à conquérir la Toison d’or"},{"id":"d2","texte":"Change les compagnons d’Ulysse en porcs"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"C’est **lie** : une défixion est un « lien » magique (καταδεσμός) qui attache la langue, les jambes ou le cœur de quelqu’un."},{"cle":{"type":"zone","ids":["m25"]},"explication":"C’est le **plomb** : on gravait la malédiction sur une fine lame de plomb, qu’on roulait ensuite."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le graveur veut **réduire Théagénès au silence devant les juges** : c’est l’usage classique des tablettes de défixion, qui « lient » la langue d’un adversaire au tribunal."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Circé** (Odyssée, chant X), **Simaitha** (Théocrite, Idylle II) et **Médée** (Argonautiques, puis tragédie d’Euripide) sont trois magiciennes de la littérature."}]$ex$::jsonb),
  ('c65f48da-c114-5d85-89c8-a369b5236880'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Remède ou poison ?","competence":"comprendre-langue","situation":"Un pharmacien d’Athènes colle une étiquette sur chaque flacon. Mais un même mot grec, φάρμακον, lui pose problème : il veut dire deux choses contraires.","documents":[{"id":"voc","type":"tableau","titre":"Fiche de vocabulaire","colonnes":["Mot grec","Sens","Mot français"],"lignes":[["μάγος","mage, prêtre perse","?"],["φάρμακον","remède, poison, charme","?"],["ἐπῳδή","incantation (chant sur)","?"],["καταδεσμός","lien magique","—"]],"enteteLignes":true},{"id":"phedre","type":"texte","genre":"source","titre":"Le cadeau du dieu Theuth","blocs":["Le dieu Theuth offre l’écriture au roi d’Égypte comme un remède pour la mémoire.","Le roi répond que ce *pharmakon* risque au contraire de rendre les hommes oublieux."],"source":"D’après Platon, *Phèdre* (IVe siècle av. J.-C.) — texte adapté"}],"questions":[{"enonce":"Relie chaque mot grec au mot français qui en est l’héritier.","aide":"Lis la troisième colonne de la fiche : elle est à compléter.","type":"association","gauche":[{"id":"g0","texte":"μάγος (magos)"},{"id":"g1","texte":"φάρμακον (pharmakon)"},{"id":"g2","texte":"ἐπῳδή (epode)"}],"droite":[{"id":"d0","texte":"pharmacie"},{"id":"d1","texte":"magie"},{"id":"d2","texte":"épode"}]},{"enonce":"Touche le mot qui montre le côté positif du pharmakon selon Theuth.","aide":"Theuth présente l’écriture comme une aide.","type":"zone","document":"phedre","multiple":false},{"enonce":"Pourquoi le mot φάρμακον convient-il bien à l’écriture dans ce texte ?","aide":"Compare ce que dit Theuth et ce que répond le roi.","type":"choix","options":[{"id":"a","texte":"Parce que l’écriture sert surtout à guérir les maladies des hommes"},{"id":"b","texte":"Parce qu’il peut à la fois aider la mémoire et finir par l’affaiblir"},{"id":"c","texte":"Parce que l’écriture est un poison mortel que le roi fait interdire"},{"id":"d","texte":"Parce que l’écriture est une formule magique réservée aux prêtres"}],"multiple":false},{"enonce":"Touche, dans la fiche, la case qui donne le sens de καταδεσμός.","aide":"Cherche la ligne du mot καταδεσμός, puis la deuxième colonne.","type":"zone","document":"voc","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"**μάγος** a donné « magie », **φάρμακον** « pharmacie » et **ἐπῳδή** (le chant qu’on prononce sur quelqu’un) « épode »."},{"cle":{"type":"zone","ids":["m12"]},"explication":"Pour Theuth, l’écriture est un **remède** : elle doit aider la mémoire."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le mot a deux sens : **remède pour Theuth, poison pour le roi**. Le même objet peut aider ou nuire, exactement comme le φάρμακον."},{"cle":{"type":"zone","ids":["r3c1"]},"explication":"Un καταδεσμός est un **lien magique** : c’est le nom des tablettes de défixion."}]$ex$::jsonb),
  ('c65f48da-c114-5d85-89c8-a369b5236880'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Croire, savoir, douter","competence":"argumenter","situation":"Dans la Grèce ancienne, on grave des malédictions sur du plomb et on écrit des traités de médecine. Compare deux textes pour voir comment les Grecs pouvaient croire, savoir et douter.","documents":[{"id":"hippo","type":"texte","genre":"source","titre":"Un médecin à propos de l’épilepsie","blocs":["Certains prétendent que la « maladie sacrée » vient des dieux et la soignent par des purifications et des incantations.","Pour moi, cette maladie n’est pas plus divine que les autres : elle a, comme elles, une cause naturelle, et on peut la soigner en observant le malade."],"source":"D’après *De la maladie sacrée*, traité du *Corpus hippocratique* (Ve siècle av. J.-C.) — texte adapté"},{"id":"iynx","type":"texte","genre":"source","titre":"Simaitha, la nuit","blocs":["La lune brille. Simaitha, seule, fait tourner sa petite roue magique.","« Iynx, attire vers ma maison cet homme qui est le mien. »"],"source":"D’après Théocrite, *Idylle* II, *Les Magiciennes* (IIIe siècle av. J.-C.) — texte adapté"}],"questions":[{"enonce":"Touche les deux mots qui donnent l’explication du médecin.","aide":"Il cherche une origine qui appartient à la nature, pas aux dieux.","type":"zone","document":"hippo","multiple":true},{"enonce":"Range ces gestes selon qu’ils cherchent à contraindre les puissances invisibles ou à les prier.","aide":"La magie promet un résultat grâce à la formule exacte ; la religion civique honore les dieux.","type":"categories","categories":[{"id":"c0","texte":"Contraindre (magie)"},{"id":"c1","texte":"Prier (religion civique)"}],"items":[{"id":"i0","texte":"Faire tourner l’iynx en répétant une formule pour forcer un amant à revenir"},{"id":"i1","texte":"Offrir un sacrifice à Athéna lors des Panathénées, au nom de la cité"},{"id":"i2","texte":"Demander aux dieux de protéger la cité, sans rien exiger de précis"},{"id":"i3","texte":"Réciter un nom divin étrange pris dans un papyrus pour obtenir un pouvoir"},{"id":"i4","texte":"Lier la langue d’un adversaire avec un clou planté dans une lame de plomb"}]},{"enonce":"Quelle attitude le médecin adopte-t-il face aux guérisseurs qui utilisent des incantations ?","aide":"Relis la deuxième phrase : que propose-t-il à la place ?","type":"choix","options":[{"id":"a","texte":"Il les consulte en secret pour connaître les volontés des dieux"},{"id":"b","texte":"Il les accuse d’impiété devant les juges de la cité par écrit"},{"id":"c","texte":"Il doute de leur pouvoir et cherche une cause qu’on peut observer"},{"id":"d","texte":"Il croit à leur pouvoir mais préfère soigner sans aucune incantation"}],"multiple":false},{"enonce":"Que montre le rapprochement des deux documents ?","aide":"Les deux attitudes existent-elles dans le même monde ?","type":"choix","options":[{"id":"a","texte":"Que tous les Grecs rejetaient la magie dès l’époque de Théocrite, au IIIe siècle"},{"id":"b","texte":"Que le monde grec abrite à la fois la croyance à la magie et la médecine rationnelle"},{"id":"c","texte":"Que la médecine grecque est née de la magie de Simaitha et de son iynx magique"},{"id":"d","texte":"Que les magiciennes étaient punies par les médecins hippocratiques de leur cité"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m35","m36"]},"explication":"Pour le médecin, la maladie a une **cause naturelle** : on peut l’observer, donc la comprendre."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"La **magie** prétend **contraindre** (l’iynx, la lame de plomb, le nom divin) ; la **religion civique** se contente de **prier** et d’honorer les dieux au nom de tous."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il **doute** des incantations et veut **observer le malade** : c’est l’attitude du savoir rationnel."},{"cle":{"type":"choix","ids":["b"]},"explication":"Simaitha **croit** à son iynx, le médecin **sait** par l’observation et **doute** des charlatans : croire, savoir et douter **coexistent** chez les Grecs."}]$ex$::jsonb),
  ('8c10ac53-2137-5144-8589-7dbf52245db5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les penseurs de la côte d’Ionie","competence":"lire-tableau","situation":"Sur la côte d’Ionie, des hommes cherchent l’ἀρχή, le principe de toutes choses. Un tableau résume les réponses de quelques-uns d’entre eux.","documents":[{"id":"pens","type":"tableau","titre":"Des penseurs et leur principe","colonnes":["Penseur","Cité","Principe (ἀρχή)"],"lignes":[["Thalès","Milet","l’eau"],["Anaximandre","Milet","l’illimité (ἄπειρον)"],["Anaximène","Milet","l’air"],["Héraclite","Éphèse","le feu et le devenir"],["Parménide","Élée","l’être"],["Démocrite","Abdère","les atomes et le vide"]],"enteteLignes":true}],"questions":[{"enonce":"Combien de penseurs du tableau viennent de Milet ?","aide":"Compte les lignes où la deuxième colonne dit « Milet ».","type":"nombre","unite":"penseurs"},{"enonce":"Touche la case qui donne le principe d’Héraclite.","aide":"Cherche la ligne d’Héraclite, puis la dernière colonne.","type":"zone","document":"pens","multiple":false},{"enonce":"Relie chaque mot grec à son sens.","aide":"Le passage du muthos au logos est celui du récit à la raison.","type":"association","gauche":[{"id":"g0","texte":"μῦθος (muthos)"},{"id":"g1","texte":"λόγος (logos)"},{"id":"g2","texte":"ἀρχή (arkhe)"},{"id":"g3","texte":"φύσις (phusis)"}],"droite":[{"id":"d0","texte":"la parole raisonnée, la raison"},{"id":"d1","texte":"le principe, le commencement"},{"id":"d2","texte":"la nature"},{"id":"d3","texte":"le récit"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3 penseurs","explication":"**3** penseurs viennent de Milet : Thalès, Anaximandre et Anaximène."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"Pour Héraclite, le principe est **le feu et le devenir** : tout s’écoule."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"**μῦθος** est le récit, **λόγος** la parole raisonnée, **ἀρχή** le principe, **φύσις** la nature : ces quatre mots ont donné « mythe », « logique », « archéologie » et « physique »."}]$ex$::jsonb),
  ('8c10ac53-2137-5144-8589-7dbf52245db5'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Une phrase de philosophe","competence":"comprendre-langue","situation":"Tu lis une courte phrase grecque sur la recherche des philosophes, puis tu croises avec les savants d’Alexandrie.","documents":[{"id":"ph","type":"texte","genre":"source","titre":"Phrase de philosophe","blocs":["οἱ φιλόσοφοι τὴν ἀρχὴν τοῦ κόσμου ζητοῦσιν."],"source":"Phrase grecque écrite pour l’exercice"},{"id":"alex","type":"tableau","titre":"Les savants d’Alexandrie","colonnes":["Savant","Découverte"],"lignes":[["Euclide","Les Éléments, fondement de la géométrie"],["Aristarque de Samos","La Terre tourne autour du Soleil"],["Ératosthène","La circonférence de la Terre mesurée grâce à l’ombre"],["Archimède","La poussée des liquides et le levier"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe conjugué de la phrase.","aide":"Il se termine par -σιν, marque de la 3e personne du pluriel.","type":"zone","document":"ph","multiple":false},{"enonce":"Touche le mot qui signifie « le principe ».","aide":"Il est à l’accusatif, précédé de τὴν.","type":"zone","document":"ph","multiple":false},{"enonce":"Quelle est la traduction de la phrase ?","aide":"Lis l’article : οἱ est un nominatif pluriel. Le verbe est au présent.","type":"choix","options":[{"id":"a","texte":"Les philosophes ont trouvé le commencement du monde"},{"id":"b","texte":"Le philosophe cherche les principes des cités"},{"id":"c","texte":"Les philosophes cherchent le principe du monde"},{"id":"d","texte":"Les dieux gouvernent le principe des philosophes"}],"multiple":false},{"enonce":"Relie chaque savant à sa découverte.","aide":"Utilise le tableau du document 2.","type":"association","gauche":[{"id":"g0","texte":"Euclide"},{"id":"g1","texte":"Aristarque de Samos"},{"id":"g2","texte":"Ératosthène"},{"id":"g3","texte":"Archimède"}],"droite":[{"id":"d0","texte":"La mesure de la Terre par les ombres"},{"id":"d1","texte":"La poussée des liquides"},{"id":"d2","texte":"Les Éléments de géométrie"},{"id":"d3","texte":"La Terre tourne autour du Soleil"}]},{"enonce":"Complète : la racine ἀρχή a donné un mot pour la science des choses anciennes.","aide":"Le mot commence par « arch- » et finit par « -logie ».","type":"trous","segments":["ἀρχή a donné le mot « ",0," », la science des choses anciennes."],"banque":["logique","géographie","hypothèse","archéologie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**ζητοῦσιν** est le verbe (ζητέω, « chercher »), à la 3e personne du pluriel du présent."},{"cle":{"type":"zone","ids":["m3"]},"explication":"**ἀρχήν** est l’accusatif de ἀρχή : c’est le complément d’objet de ζητοῦσιν."},{"cle":{"type":"choix","ids":["c"]},"explication":"οἱ φιλόσοφοι (sujet, pluriel) + ζητοῦσιν (présent) + τὴν ἀρχήν (objet) + τοῦ κόσμου (génitif) : **Les philosophes cherchent le principe du monde.**"},{"cle":{"type":"association","paires":{"g2":"d0","g3":"d1","g0":"d2","g1":"d3"}},"explication":"**Euclide** écrit les Éléments, **Aristarque** place le Soleil au centre, **Ératosthène** mesure la Terre, **Archimède** découvre la poussée des liquides."},{"cle":{"type":"trous","trous":[["archeologie"]]},"affichage":"archéologie","explication":"« **Archéologie** » vient de ἀρχαῖος (ancien), de la famille de ἀρχή, « commencement » ; l’archéologue étudie les origines."}]$ex$::jsonb),
  ('8c10ac53-2137-5144-8589-7dbf52245db5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Raconter ou expliquer ?","competence":"argumenter","situation":"Mathilde prépare un exposé sur le passage du muthos au logos. Elle dispose d’une frise de repères et d’un texte de Xénophane.","documents":[{"id":"fr","type":"frise","titre":"Repères de la pensée grecque","debut":-600,"fin":-200,"pas":50,"periodes":[{"id":"z1","debut":-431,"fin":-404,"nom":"Guerre du Péloponnèse","teinte":"ambre"}],"evenements":[{"id":"z2","date":-585,"nom":"Éclipse de Thalès"},{"id":"z3","date":-212,"nom":"Mort d’Archimède"}]},{"id":"xen","type":"texte","genre":"source","titre":"Les dieux des hommes","blocs":["Les hommes se figurent des dieux à leur image : les Éthiopiens les font noirs, les Thraces aux yeux bleus et aux cheveux roux.","Si les bœufs avaient des mains, ils dessineraient des dieux semblables à des bœufs."],"source":"D’après Xénophane de Colophon, fragments (VIe siècle av. J.-C.) — texte adapté"}],"questions":[{"enonce":"Touche le repère où Thalès aurait prédit une éclipse.","aide":"Cherche la date la plus ancienne de la frise.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent l’éclipse prédite par Thalès (585) de la mort d’Archimède (212) ?","aide":"Les deux dates sont avant J.-C. : soustrais la plus petite de la plus grande.","type":"nombre","unite":"ans"},{"enonce":"Que reproche Xénophane aux hommes dans ce texte ?","aide":"Que font les Éthiopiens, les Thraces, puis les bœufs ?","type":"choix","options":[{"id":"a","texte":"D’offrir trop de sacrifices aux dieux dans les cités grecques"},{"id":"b","texte":"De refuser de croire que les dieux existent et qu’ils ont des pouvoirs"},{"id":"c","texte":"De prêter aux dieux leur propre apparence, au lieu de les concevoir autrement"},{"id":"d","texte":"D’ignorer que les dieux vivent sur l’Olympe avec Zeus"}],"multiple":false},{"enonce":"Range chaque explication selon qu’elle relève du muthos ou du logos.","aide":"Le muthos raconte l’action des dieux ; le logos cherche une cause qu’on peut vérifier.","type":"categories","categories":[{"id":"c0","texte":"Muthos (récit)"},{"id":"c1","texte":"Logos (raison)"}],"items":[{"id":"i0","texte":"Le médecin hippocratique observe les symptômes et cherche une cause naturelle"},{"id":"i1","texte":"Hérodote mène une enquête et interroge des témoins"},{"id":"i2","texte":"Les saisons reviennent parce que Perséphone rejoint sa mère"},{"id":"i3","texte":"Thalès cherche dans l’eau le principe de toutes choses"},{"id":"i4","texte":"Zeus lance la foudre quand il est en colère"},{"id":"i5","texte":"Poséidon ébranle la terre quand il frappe le sol de son trident"}]},{"enonce":"Platon invente lui-même des mythes. Que montre cela ?","aide":"Le passage du muthos au logos ne se fait pas d’un coup.","type":"choix","options":[{"id":"a","texte":"Que la raison grecque continue de raconter ce que le raisonnement ne suffit pas à dire"},{"id":"b","texte":"Que les mythes étaient réservés aux enfants et aux gens sans instruction"},{"id":"c","texte":"Que le logos avait complètement disparu de la pensée grecque après Thalès"},{"id":"d","texte":"Que Platon ne faisait aucune différence entre un récit et une preuve rationnelle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Thalès aurait prédit une **éclipse en 585 av. J.-C.** : c’est l’un des repères de la pensée rationnelle."},{"cle":{"type":"nombre","valeur":373,"tolerance":0},"affichage":"373 ans","explication":"585 − 212 = **373 ans**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Chaque groupe dessine des dieux **à son image** : Xénophane critique cet anthropomorphisme, y compris celui d’Homère."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Les récits où **un dieu agit** sont du **muthos** ; l’observation, l’enquête et la recherche d’un principe relèvent du **logos**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Muthos et logos ne se **succèdent** pas d’un coup : la raison grecque **doute**, mais elle continue de **raconter**."}]$ex$::jsonb),
  ('ecf078aa-23ae-5217-af25-091acf0edcf3'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La chaîne des maîtres","competence":"se-reperer-temps","situation":"En Grèce, le savoir passe de personne à personne. Voici la chaîne la plus célèbre, de Socrate à Alexandre le Grand.","documents":[{"id":"ch","type":"chaine","disposition":"ligne","noeuds":[{"id":"z1","texte":"Socrate"},{"id":"z2","texte":"Platon"},{"id":"z3","texte":"Aristote"},{"id":"z4","texte":"Alexandre"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Touche le précepteur d’Alexandre le Grand.","aide":"Il a été élève de Platon pendant vingt ans.","type":"zone","document":"ch","multiple":false},{"enonce":"Touche le philosophe qui fonde l’Académie.","aide":"C’est l’élève de Socrate et le maître d’Aristote.","type":"zone","document":"ch","multiple":false},{"enonce":"Relie chaque école à son fondateur.","aide":"Deux fondateurs sont dans la chaîne ; les deux autres sont à Athènes aussi.","type":"association","gauche":[{"id":"g0","texte":"L’Académie"},{"id":"g1","texte":"Le Lycée"},{"id":"g2","texte":"Le Jardin"},{"id":"g3","texte":"Le Portique"}],"droite":[{"id":"d0","texte":"Aristote"},{"id":"d1","texte":"Zénon"},{"id":"d2","texte":"Platon"},{"id":"d3","texte":"Épicure"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"**Aristote** est le précepteur d’Alexandre à partir de 343 av. J.-C."},{"cle":{"type":"zone","ids":["z2"]},"explication":"**Platon** fonde l’Académie vers 387 av. J.-C., dans le jardin du héros Akadémos."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"L’**Académie** est de Platon, le **Lycée** d’Aristote, le **Jardin** d’Épicure (l’amitié et le plaisir mesuré), le **Portique** de Zénon (la vertu stoïcienne)."}]$ex$::jsonb),
  ('ecf078aa-23ae-5217-af25-091acf0edcf3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Qui instruit qui ?","competence":"comprendre-langue","situation":"Deux phrases grecques écrites pour l’exercice parlent de maîtres et d’élèves. Lis bien les articles : ils disent qui fait l’action.","documents":[{"id":"a","type":"texte","genre":"source","titre":"Phrase A","blocs":["ὁ Σωκράτης οὐδὲν γράφει· τοὺς ἀνθρώπους ἐρωτᾷ."],"source":"Phrase grecque écrite pour l’exercice"},{"id":"b","type":"texte","genre":"source","titre":"Phrase B","blocs":["ὁ Ἀριστοτέλης τὸν Ἀλέξανδρον παιδεύει."],"source":"Phrase grecque écrite pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui veut dire « rien ».","aide":"Il commence par οὐ, la négation.","type":"zone","document":"a","multiple":false},{"enonce":"Touche le nom de celui qui enseigne, le sujet de la phrase.","aide":"Il est précédé de ὁ, article du nominatif masculin.","type":"zone","document":"b","multiple":false},{"enonce":"Quelle est la traduction de la phrase B ?","aide":"Regarde l’article devant chaque nom : τὸν est à l’accusatif.","type":"choix","options":[{"id":"a","texte":"Aristote est instruit par Alexandre"},{"id":"b","texte":"Alexandre et Aristote s’instruisent"},{"id":"c","texte":"Alexandre instruit Aristote"},{"id":"d","texte":"Aristote instruit Alexandre"}],"multiple":false},{"enonce":"Relie chaque mot grec à son sens.","aide":"Le pédagogue n’était pas le professeur.","type":"association","gauche":[{"id":"g0","texte":"σχολή (skhole)"},{"id":"g1","texte":"μαθητής (mathetes)"},{"id":"g2","texte":"παιδαγωγός (paidagogos)"},{"id":"g3","texte":"διδάσκαλος (didaskalos)"}],"droite":[{"id":"d0","texte":"l’esclave qui conduit l’enfant chez ses maîtres"},{"id":"d1","texte":"le loisir, d’où « école »"},{"id":"d2","texte":"le maître, d’où « didactique »"},{"id":"d3","texte":"celui qui apprend"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**οὐδὲν** signifie « rien » : « Socrate n’écrit rien ; il interroge les hommes. »"},{"cle":{"type":"zone","ids":["m1"]},"explication":"**Ἀριστοτέλης** est au nominatif (article ὁ) : c’est lui qui fait l’action."},{"cle":{"type":"choix","ids":["d"]},"explication":"ὁ Ἀριστοτέλης est le sujet, τὸν Ἀλέξανδρον l’objet : **Aristote instruit Alexandre.**"},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g3":"d2","g1":"d3"}},"explication":"**σχολή** est le loisir, **μαθητής** celui qui apprend, **παιδαγωγός** celui qui conduit (ἄγω) l’enfant (παῖς), **διδάσκαλος** le maître."}]$ex$::jsonb),
  ('ecf078aa-23ae-5217-af25-091acf0edcf3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le maître et ses disciples","competence":"argumenter","situation":"Une élève prépare un exposé sur la transmission du savoir à Athènes. Elle croise une frise et un mot célèbre prêté à Aristote.","documents":[{"id":"fr","type":"frise","titre":"Maîtres et écoles","debut":-400,"fin":-300,"pas":25,"evenements":[{"id":"z1","date":-399,"nom":"Procès de Socrate"},{"id":"z2","date":-387,"nom":"Académie de Platon"},{"id":"z3","date":-343,"nom":"Aristote précepteur"},{"id":"z4","date":-335,"nom":"Fondation du Lycée"}]},{"id":"mot","type":"texte","genre":"source","titre":"Un mot célèbre","blocs":["« Ami de Platon, mais plus encore ami de la vérité. »"],"source":"Mot traditionnellement prêté à Aristote"}],"questions":[{"enonce":"Touche l’événement qui suit immédiatement la fondation de l’Académie.","aide":"Lis les dates : cherche celle qui vient juste après 387.","type":"zone","document":"fr","multiple":false},{"enonce":"Combien d’années séparent la fondation de l’Académie (387) de celle du Lycée (335) ?","aide":"Soustrais les deux dates avant J.-C.","type":"nombre","unite":"ans"},{"enonce":"Range chaque trait selon qu’il désigne Socrate ou les sophistes.","aide":"Un seul de ces maîtres demandait de l’argent.","type":"categories","categories":[{"id":"c0","texte":"Socrate"},{"id":"c1","texte":"Les sophistes"}],"items":[{"id":"i0","texte":"Affirmer que l’homme est la mesure de toutes choses"},{"id":"i1","texte":"Se dire « sage-femme » des esprits, comme sa mère"},{"id":"i2","texte":"Enseigner contre salaire l’art de persuader"},{"id":"i3","texte":"Refuser de s’évader avant de boire la ciguë"},{"id":"i4","texte":"Interroger ses interlocuteurs sans rien écrire"}]},{"enonce":"Que montre le mot prêté à Aristote sur la relation maître-disciple ?","aide":"Il se dit « ami de Platon », mais il place quelque chose au-dessus.","type":"choix","options":[{"id":"a","texte":"Qu’un disciple doit accepter sans discuter toutes les idées de son maître"},{"id":"b","texte":"Qu’un disciple reste libre de critiquer son maître au nom de la vérité"},{"id":"c","texte":"Qu’Aristote a rompu toute relation avec l’Académie dès son arrivée"},{"id":"d","texte":"Qu’Aristote a fini par oublier tout ce que lui avait appris Platon"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Après l’**Académie (387)**, l’événement suivant est **Aristote précepteur d’Alexandre (343)**."},{"cle":{"type":"nombre","valeur":52,"tolerance":0},"affichage":"52 ans","explication":"387 − 335 = **52 ans**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0"}},"explication":"**Socrate** n’écrit rien, pratique la maïeutique et refuse de s’évader ; les **sophistes**, comme Protagoras, enseignent contre salaire l’art de persuader."},{"cle":{"type":"choix","ids":["b"]},"explication":"La relation maître-disciple n’est pas la **soumission** : Aristote critique Platon, tout en restant son ami."}]$ex$::jsonb),
  ('92a8bef1-ae5a-5b7c-882c-b9d32ca932a1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le premier verset de Jean","competence":"analyser-texte","situation":"Le Nouveau Testament est écrit en grec commun, la κοινή. Voici le début célèbre de l’Évangile de Jean : deux mots grecs y portent beaucoup de sens.","documents":[{"id":"jn","type":"texte","genre":"source","titre":"Évangile de Jean, début","blocs":["Ἐν ἀρχῇ ἦν ὁ λόγος"],"source":"Évangile selon Jean 1, 1 (début), en grec commun"}],"questions":[{"enonce":"Touche le mot grec qui signifie « le commencement ».","aide":"C’est le mot qui a donné « archéologie » et « monarchie ».","type":"zone","document":"jn","multiple":false},{"enonce":"Touche le mot que les philosophes grecs employaient pour dire « la raison ».","aide":"C’est aussi la racine de « logique ».","type":"zone","document":"jn","multiple":false},{"enonce":"Que fait l’Évangile du mot λόγος ?","aide":"Le christianisme emprunte à la culture grecque sa langue et ses concepts.","type":"choix","options":[{"id":"a","texte":"Il l’emprunte aux philosophes pour en faire un nom du Christ"},{"id":"b","texte":"Il l’abandonne parce que les philosophes l’avaient déformé"},{"id":"c","texte":"Il l’emploie seulement pour parler de la parole des hommes"},{"id":"d","texte":"Il le traduit par un mot hébreu qui n’existe pas en grec"}],"multiple":false},{"enonce":"Relie chaque mot grec à son sens chrétien.","aide":"Chaque mot avait d’abord un sens courant en grec.","type":"association","gauche":[{"id":"g0","texte":"ἐκκλησία (ekklesia)"},{"id":"g1","texte":"εὐαγγέλιον (euangelion)"},{"id":"g2","texte":"ἐπίσκοπος (episkopos)"},{"id":"g3","texte":"βάπτισμα (baptisma)"}],"droite":[{"id":"d0","texte":"l’Église"},{"id":"d1","texte":"le baptême"},{"id":"d2","texte":"l’Évangile"},{"id":"d3","texte":"l’évêque"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**ἀρχῇ** est le datif de ἀρχή : « au commencement »."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**λόγος** est le mot des philosophes : parole, raison. Ici il désigne le Verbe."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le λόγος **des philosophes devient le nom du Christ** : le christianisme emprunte ses concepts au grec."},{"cle":{"type":"association","paires":{"g0":"d0","g3":"d1","g1":"d2","g2":"d3"}},"explication":"**ἐκκλησία** (assemblée) → l’Église ; **εὐαγγέλιον** (bonne nouvelle) → l’Évangile ; **ἐπίσκοπος** (surveillant) → l’évêque ; **βάπτισμα** (immersion) → le baptême."}]$ex$::jsonb),
