ublic"},{"id":"c1","texte":"Culte à mystères"}],"items":[{"id":"i0","texte":"Un rite accompli au nom de tous les citoyens"},{"id":"i1","texte":"Un sacrifice offert à Athéna lors des Panathénées"},{"id":"i2","texte":"Une initiation secrète dont on ne révèle rien aux autres"},{"id":"i3","texte":"Une fête où toute la cité honore ses dieux"},{"id":"i4","texte":"Une lamelle d’or qui guide l’âme du mort dans l’au-delà"}]},{"enonce":"Touche la ligne qui dit devant qui Paul s’adresse.","aide":"Cherche le mot « Auditoire ».","type":"zone","document":"autel","multiple":false}]}$ex$::jsonb,
