  ('78cc1c98-4d12-5af3-9902-fc6bcd7b73b3'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Lire avant de traduire","competence":"manier-langue","situation":"Tu prépares la traduction d’une courte phrase. Applique la méthode : repère les particules, les verbes, puis cherche au dictionnaire.","documents":[{"id":"ph","type":"texte","genre":"source","titre":"Phrase à traduire","blocs":["οἱ μὲν ναῦται ἔμενον, ὁ δὲ κυβερνήτης εἶδεν νῆσον."],"source":"Phrase grecque écrite pour l’exercice"}],"questions":[{"enonce":"Touche les deux particules qui opposent « d’un côté » et « de l’autre ».","aide":"Elles se placent en deuxième position, après l’article.","type":"zone","document":"ph","multiple":true},{"enonce":"Touche le verbe qui se traduit ici par « vit ».","aide":"C’est un aoriste irrégulier, celui de ὁράω.","type":"zone","document":"ph","multiple":false},{"enonce":"Relie chaque aoriste irrégulier au verbe sous lequel on le cherche au dictionnaire.","aide":"On cherche toujours le verbe à la 1re personne du présent.","type":"association","gauche":[{"id":"g0","texte":"εἶπον (eipon)"},{"id":"g1","texte":"εἶδον (eidon)"},{"id":"g2","texte":"ἦλθον (elthon)"}],"droite":[{"id":"d0","texte":"λέγω (lego)"},{"id":"d1","texte":"ἔρχομαι (erkhomai)"},{"id":"d2","texte":"ὁράω (horao)"}]},{"enonce":"Quelle est la traduction de la phrase ?","aide":"ἔμενον est à l’imparfait de μένω ; εἶδεν est un aoriste.","type":"choix","options":[{"id":"a","texte":"Les marins et le pilote restèrent sur l’île"},{"id":"b","texte":"Les marins virent une île, mais le pilote resta"},{"id":"c","texte":"Les marins restaient, mais le pilote vit une île"},{"id":"d","texte":"Le marin resta et les pilotes virent une île"}],"multiple":false},{"enonce":"Remets dans l’ordre ces étapes de la méthode pour traduire le grec.","aide":"On commence par comprendre la situation et on finit par rédiger.","type":"ordre","items":[{"id":"a","texte":"Rédiger, puis relire : l’exactitude d’abord, l’élégance ensuite"},{"id":"b","texte":"Chercher chaque mot au dictionnaire sous sa forme d’entrée"},{"id":"c","texte":"Repérer les verbes conjugués et délimiter les propositions"},{"id":"d","texte":"Lire l’article avant le nom pour trouver cas, genre et nombre"},{"id":"e","texte":"Lire le chapeau et la traduction fournie autour du passage"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m5"]},"explication":"**μέν… δέ** marque l’opposition : « d’un côté… de l’autre »."},{"cle":{"type":"zone","ids":["m7"]},"explication":"**εἶδεν** est l’aoriste de ὁράω : « il vit »."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**εἶπον** est l’aoriste de **λέγω** (dire), **εἶδον** de **ὁράω** (voir), **ἦλθον** de **ἔρχομαι** (aller, venir)."},{"cle":{"type":"choix","ids":["c"]},"explication":"οἱ ναῦται ἔμενον (les marins restaient) + ὁ κυβερνήτης εἶδεν νῆσον (le pilote vit une île) : **« Les marins restaient, mais le pilote vit une île. »**"},{"cle":{"type":"ordre","ids":["e","c","d","b","a"]},"explication":"On lit d’abord **le chapeau**, on repère **les verbes**, puis **l’article** ; on cherche au **dictionnaire** ; on **rédige et relit** à la fin."}]$ex$::jsonb),
  ('78cc1c98-4d12-5af3-9902-fc6bcd7b73b3'::uuid, 3, 3, 15, 50, 3,
   $ex${"titre":"Préparer l’essai","competence":"argumenter","situation":"Inès prépare l’essai sur les trois textes du corpus. Elle a écrit un plan et quelques phrases de copie. Aide-la à les analyser.","documents":[{"id":"plan","type":"tableau","titre":"Le plan d’Inès","colonnes":["Partie","Textes mobilisés","Idée"],"lignes":[["I. Dire le merveilleux","Le texte grec et celui de Calvino","Deux façons de raconter l’incroyable"],["II. Faire croire","Le texte grec seul","Comment le narrateur rend son récit vraisemblable"],["III. Jouer avec le lecteur","Les trois textes","Ce que chacun fait du vrai et du faux"]],"enteteLignes":true},{"id":"copie","type":"texte","genre":"consigne","titre":"Phrases de copie d’élèves","blocs":["Le bateau est emporté par un tourbillon jusqu’à la Lune.","Comme chez Lucien, le narrateur de Calvino raconte l’incroyable avec sérieux.","Cosimo monte dans un arbre et n’en redescend plus.","Lucien imagine un voyage fantastique ; Calvino, une vie dans les arbres."],"source":"Phrases écrites pour l’exercice"}],"questions":[{"enonce":"Touche la case qui montre que la partie II ne confronte pas plusieurs textes.","aide":"Lis la colonne « Textes mobilisés » ligne par ligne.","type":"zone","document":"plan","multiple":false},{"enonce":"Range chaque phrase de copie selon ce qu’elle fait.","aide":"Une phrase qui confronte nomme les deux textes.","type":"categories","categories":[{"id":"c0","texte":"Résume un seul texte"},{"id":"c1","texte":"Confronte deux textes"}],"items":[{"id":"i0","texte":"Comme chez Lucien, le narrateur de Calvino raconte l’incroyable avec sérieux."},{"id":"i1","texte":"Lucien imagine un voyage fantastique ; Calvino, une vie dans les arbres."},{"id":"i2","texte":"Cosimo monte dans un arbre et n’en redescend plus."},{"id":"i3","texte":"Le bateau est emporté par un tourbillon jusqu’à la Lune."}]},{"enonce":"Pour le fait de langue, range ces phrases selon qu’elles identifient ou qu’elles interprètent.","aide":"Identifier, c’est donner la nature grammaticale ; interpréter, c’est dire ce qu’elle apporte au sens.","type":"categories","categories":[{"id":"c0","texte":"Identifier"},{"id":"c1","texte":"Interpréter"}],"items":[{"id":"i0","texte":"C’est un participe présent, nominatif masculin pluriel"},{"id":"i1","texte":"L’optatif exprime ici un souhait du narrateur"},{"id":"i2","texte":"Le participe donne la cause de l’action principale"},{"id":"i3","texte":"C’est un optatif aoriste, à la 3e personne du singulier"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La partie II n’utilise que **le texte grec seul** : or chaque paragraphe doit confronter au moins deux textes du corpus."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"Les phrases qui **nomment Lucien ET Calvino** confrontent ; celles qui ne parlent que d’un récit le **résument**, ce qui est le défaut n° 1 de l’essai."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0"}},"explication":"**Identifier** : mode, temps, cas, personne. **Interpréter** : ce que l’optatif ou le participe apporte au sens du passage."}]$ex$::jsonb),
  ('06040f23-2e3c-5a66-9bf7-f8ec7554bed1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Les formes de πόλις et de βασιλεύς","competence":"lire-tableau","situation":"Pour lire un texte grec, il faut reconnaître les cas. Voici la déclinaison de deux noms de la 3e déclinaison.","documents":[{"id":"decl","type":"tableau","titre":"Deux noms de la 3e déclinaison","colonnes":["Cas","πόλις","βασιλεύς"],"lignes":[["Nominatif","πόλις","βασιλεύς"],["Accusatif","πόλιν","βασιλέα"],["Génitif","πόλεως","βασιλέως"],["Datif","πόλει","βασιλεῖ"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’accusatif de πόλις.","aide":"Cherche la ligne « Accusatif », puis la colonne de πόλις.","type":"zone","document":"decl","multiple":false},{"enonce":"Touche le datif de βασιλεύς.","aide":"Cherche la ligne « Datif », puis la colonne de βασιλεύς.","type":"zone","document":"decl","multiple":false},{"enonce":"Relie chaque nominatif à son génitif.","aide":"Le génitif donne le radical : on le cherche toujours au dictionnaire.","type":"association","gauche":[{"id":"g0","texte":"φύλαξ (phulax)"},{"id":"g1","texte":"βασιλεύς (basileus)"},{"id":"g2","texte":"γένος (genos)"},{"id":"g3","texte":"πόλις (polis)"}],"droite":[{"id":"d0","texte":"βασιλέως (basileos)"},{"id":"d1","texte":"φύλακος (phulakos)"},{"id":"d2","texte":"πόλεως (poleos)"},{"id":"d3","texte":"γένους (genous)"}]},{"enonce":"Pourquoi cherche-t-on toujours le génitif d’un nom de la 3e déclinaison ?","aide":"Regarde πόλις et πόλεως : que reste-t-il du mot ?","type":"choix","options":[{"id":"a","texte":"Parce qu’il indique toujours le genre du nom et son nombre"},{"id":"b","texte":"Parce qu’il est le seul cas que l’on rencontre dans les textes"},{"id":"c","texte":"Parce qu’il donne le radical sur lequel se forment les autres cas"},{"id":"d","texte":"Parce qu’il s’écrit toujours comme le nominatif pluriel du mot"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"L’accusatif de πόλις est **πόλιν**."},{"cle":{"type":"zone","ids":["r3c2"]},"explication":"Le datif de βασιλεύς est **βασιλεῖ**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"Le **génitif** donne le radical de chaque nom : φύλακος, βασιλέως, γένους, πόλεως."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le nominatif ne montre pas toujours le radical ; le **génitif** le donne, et les autres cas s’en déduisent."}]$ex$::jsonb),
  ('06040f23-2e3c-5a66-9bf7-f8ec7554bed1'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"La cité fut gardée","competence":"manier-langue","situation":"Une phrase au passif et un tableau de comparatifs : voilà deux pièges classiques de la Terminale. Lis les formes avec soin.","documents":[{"id":"ph","type":"texte","genre":"source","titre":"Phrase à analyser","blocs":["ἡ πόλις ὑπὸ τοῦ βασιλέως ἐφυλάχθη."],"source":"Phrase grecque écrite pour l’exercice"},{"id":"comp","type":"tableau","titre":"Comparatifs et superlatifs","colonnes":["Adjectif","Comparatif","Superlatif"],"lignes":[["ἀγαθός","ἀμείνων","ἄριστος"],["κακός","κακίων","κάκιστος"],["μέγας","μείζων","?"],["πολύς","πλείων","?"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe à l’aoriste passif.","aide":"Cherche le suffixe -θη-.","type":"zone","document":"ph","multiple":false},{"enonce":"Touche le mot qui désigne celui qui garde la cité (complément d’agent).","aide":"Il suit ὑπὸ et il est au génitif.","type":"zone","document":"ph","multiple":false},{"enonce":"Quelle est la traduction de la phrase ?","aide":"ἡ πόλις est le sujet ; le verbe est passif.","type":"choix","options":[{"id":"a","texte":"Le roi garda la cité pendant la nuit"},{"id":"b","texte":"La cité gardera le roi de ses ennemis"},{"id":"c","texte":"La cité fut gardée par le roi"},{"id":"d","texte":"La cité garde le roi avec courage"}],"multiple":false},{"enonce":"Complète les superlatifs manquants du tableau.","aide":"Regarde les autres lignes : le superlatif finit en -ιστος.","type":"trous","segments":["Le superlatif de μέγας est ",0," et celui de πολύς est ",1,"."],"banque":["πλεῖστος (pleistos)","μέγιστος (megistos)","ἄριστος (aristos)","κάκιστος (kakistos)","μείζων (meizon)"]},{"enonce":"Range ces formes de λύω selon leur voix.","aide":"Le suffixe -θη- signale le passif ; le moyen a un -σα- et une terminaison en -μην ou -σθαι.","type":"categories","categories":[{"id":"c0","texte":"Aoriste moyen"},{"id":"c1","texte":"Aoriste passif"}],"items":[{"id":"i0","texte":"λυθῆναι (luthenai)"},{"id":"i1","texte":"ἐλυσάμην (elusamen)"},{"id":"i2","texte":"ἐλύθην (eluthen)"},{"id":"i3","texte":"λύσασθαι (lusasthai)"},{"id":"i4","texte":"λυθείς (lutheis)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5"]},"explication":"**ἐφυλάχθη** est l’aoriste passif de φυλάττω : le suffixe -θη- signale le passif."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**βασιλέως** est le complément d’agent : ὑπὸ + génitif."},{"cle":{"type":"choix","ids":["c"]},"explication":"ἡ πόλις (sujet) + ὑπὸ τοῦ βασιλέως (agent) + ἐφυλάχθη (aoriste passif) : **« La cité fut gardée par le roi. »**"},{"cle":{"type":"trous","trous":[["megistos"],["pleistos"]]},"affichage":"μέγιστος (megistos) · πλεῖστος (pleistos)","explication":"Le superlatif de μέγας est **μέγιστος** ; celui de πολύς est **πλεῖστος**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1"}},"explication":"Le suffixe **-θη-** signale l’**aoriste passif** (ἐλύθην, λυθῆναι, λυθείς) ; ἐλυσάμην et λύσασθαι sont à l’**aoriste moyen**."}]$ex$::jsonb),
  ('06040f23-2e3c-5a66-9bf7-f8ec7554bed1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"But, temps et négation","competence":"manier-langue","situation":"Deux phrases grecques écrites pour l’exercice racontent les déplacements d’un général. Repère le but, la durée et l’époque.","documents":[{"id":"a","type":"texte","genre":"source","titre":"Phrase A","blocs":["ὁ στρατηγὸς ἔρχεται ἵνα τὴν πόλιν σώσῃ."],"source":"Phrase grecque écrite pour l’exercice"},{"id":"b","type":"texte","genre":"source","titre":"Phrase B","blocs":["ὁ στρατηγὸς τρεῖς ἡμέρας ἐν τῇ πόλει ἔμεινεν, νυκτὸς δὲ ἀπῆλθεν."],"source":"Phrase grecque écrite pour l’exercice"}],"questions":[{"enonce":"Touche le verbe au subjonctif.","aide":"Il se termine par -ῃ, avec une voyelle longue.","type":"zone","document":"a","multiple":false},{"enonce":"Que signifie la phrase A ?","aide":"ἵνα + subjonctif exprime le but.","type":"choix","options":[{"id":"a","texte":"Le général vient pour sauver la cité"},{"id":"b","texte":"Le général vient parce qu’il a sauvé la cité"},{"id":"c","texte":"Le général vient si la cité est sauvée"},{"id":"d","texte":"Le général vient alors que la cité est sauvée"}],"multiple":false},{"enonce":"Touche les deux mots qui disent combien de temps le général reste.","aide":"Ils sont à l’accusatif : c’est l’accusatif de durée.","type":"zone","document":"b","multiple":true},{"enonce":"Touche le mot qui dit à quel moment il repart.","aide":"Il est au génitif : c’est le génitif d’époque.","type":"zone","document":"b","multiple":false},{"enonce":"Range ces phrases selon la négation grecque qu’elles demandent.","aide":"οὐ nie un fait ; μή nie une volonté, une hypothèse, un but.","type":"categories","categories":[{"id":"c0","texte":"οὐ"},{"id":"c1","texte":"μή"}],"items":[{"id":"i0","texte":"Qu’il ne vienne pas ! (volonté)"},{"id":"i1","texte":"Pour qu’il ne parte pas (but)"},{"id":"i2","texte":"Il n’est pas roi (fait)"},{"id":"i3","texte":"Il ne vient pas (simple constat)"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"**σώσῃ** est un subjonctif aoriste (σώζω) : il suit ἵνα, conjonction de but."},{"cle":{"type":"choix","ids":["a"]},"explication":"**ἵνα + subjonctif** exprime le but : « Le général vient pour sauver la cité. »"},{"cle":{"type":"zone","ids":["m2","m3"]},"explication":"**τρεῖς ἡμέρας** à l’accusatif exprime la durée : « pendant trois jours »."},{"cle":{"type":"zone","ids":["m8"]},"explication":"**νυκτός** (génitif) dit l’époque : « de nuit »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0"}},"explication":"**οὐ** nie un **fait** ; **μή** nie une **volonté**, une hypothèse ou un **but**."}]$ex$::jsonb),
  ('3351e133-3794-5758-a522-0827a3d8da7d'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le vœu d’Ajax","competence":"analyser-texte","situation":"Avant de mourir, Ajax parle à son jeune fils. Les mots que tu lis sont un vers de Sophocle : un verbe y exprime un souhait.","documents":[{"id":"vers","type":"texte","genre":"poeme","titre":"Ajax à son fils","blocs":["ὦ παῖ, γένοιο πατρὸς εὐτυχέστερος"],"source":"Sophocle, *Ajax*, v. 550 (début du vers)"}],"questions":[{"enonce":"Touche le verbe à l’optatif.","aide":"Il contient un -ι- entre le radical et la terminaison.","type":"zone","document":"vers","multiple":false},{"enonce":"Touche le mot qui est un comparatif.","aide":"Il se termine par -τερος.","type":"zone","document":"vers","multiple":false},{"enonce":"Relie chaque emploi à la phrase française qui l’illustre.","aide":"Le souhait s’exprime à l’optatif seul, le potentiel avec ἄν, l’éventuel avec le subjonctif.","type":"association","gauche":[{"id":"g0","texte":"Le souhait"},{"id":"g1","texte":"Le potentiel"},{"id":"g2","texte":"L’éventuel"}],"droite":[{"id":"d0","texte":"Puisses-tu être plus heureux que ton père !"},{"id":"d1","texte":"S’il vient, il verra."},{"id":"d2","texte":"J’écouterais volontiers."}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m2"]},"explication":"**γένοιο** est un optatif aoriste de γίγνομαι, à la 2e personne : c’est un souhait."},{"cle":{"type":"zone","ids":["m4"]},"explication":"**εὐτυχέστερος** est le comparatif de εὐτυχής : « plus heureux »."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"Le **souhait** (optatif seul), le **potentiel** (optatif + ἄν) et l’**éventuel** (subjonctif + ἄν) correspondent à ces trois phrases."}]$ex$::jsonb),
  ('3351e133-3794-5758-a522-0827a3d8da7d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Naviguer vers Athènes","competence":"manier-langue","situation":"Une phrase au potentiel et un tableau d’optatifs à compléter : à toi de retrouver les formes et de dire ce qu’elles signifient.","documents":[{"id":"ph","type":"texte","genre":"source","titre":"Phrase grecque","blocs":["ἡδέως ἂν πλεύσαιμεν εἰς Ἀθήνας."],"source":"Phrase grecque écrite pour l’exercice"},{"id":"opt","type":"tableau","titre":"L’optatif de λύω et de λαμβάνω","colonnes":["Personne","Présent","Aoriste sigmatique","Aoriste thématique"],"lignes":[["1re sing.","λύοιμι","λύσαιμι","λάβοιμι"],["2e sing.","?","λύσαις","λάβοις"],["3e sing.","λύοι","λύσαι","λάβοι"],["3e plur.","λύοιεν","?","λάβοιεν"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le petit mot qui fait du verbe un potentiel.","aide":"C’est une particule de deux lettres placée avant le verbe.","type":"zone","document":"ph","multiple":false},{"enonce":"Quelle est la traduction de la phrase ?","aide":"ἄν + optatif : que « pourrait-on » faire ?","type":"choix","options":[{"id":"a","texte":"Puissions-nous naviguer vers Athènes sans danger"},{"id":"b","texte":"Si jamais nous naviguons, nous irons à Athènes"},{"id":"c","texte":"Nous avons navigué volontiers jusqu’à Athènes"},{"id":"d","texte":"Nous ferions volontiers voile vers Athènes"}],"multiple":false},{"enonce":"Complète les deux formes manquantes du tableau.","aide":"Le présent a -οι-, l’aoriste sigmatique -αι-.","type":"trous","segments":["La forme manquante de la 2e personne du présent est ",0," ; celle de la 3e personne du pluriel de l’aoriste sigmatique est ",1,"."],"banque":["λύσαιεν (lusaien)","λύοις (luois)","λύοι (luoi)","λύσαιτε (lusaite)","λάβοις (labois)"]},{"enonce":"Range ces formes d’optatif selon leur temps.","aide":"-οι- au présent et à l’aoriste thématique ; -αι- à l’aoriste sigmatique. Le radical λαβ- est celui de l’aoriste thématique.","type":"categories","categories":[{"id":"c0","texte":"Présent"},{"id":"c1","texte":"Aoriste sigmatique"},{"id":"c2","texte":"Aoriste thématique"}],"items":[{"id":"i0","texte":"λύσαιτε (lusaite)"},{"id":"i1","texte":"λύοι (luoi)"},{"id":"i2","texte":"λάβοις (labois)"},{"id":"i3","texte":"λύοιεν (luoien)"},{"id":"i4","texte":"λύσαιμεν (lusaimen)"},{"id":"i5","texte":"λάβοιμι (laboimi)"}]}]}$ex$::jsonb,
