exte":"Souhait"},{"id":"c1","texte":"Potentiel"},{"id":"c2","texte":"Éventuel"}],"items":[{"id":"i0","texte":"Il pourrait partir demain."},{"id":"i1","texte":"Je serais heureux de te voir."},{"id":"i2","texte":"Si jamais tu viens, je te verrai."},{"id":"i3","texte":"Puissions-nous être libres !"},{"id":"i4","texte":"Puisse-t-il revenir sain et sauf !"},{"id":"i5","texte":"Chaque fois que l’hiver arrive, nous restons."}]}]}$ex$::jsonb,
