nèque"},{"id":"g2","texte":"Celse"}],"droite":[{"id":"d0","texte":"Cherche les causes des séismes"},{"id":"d1","texte":"Recense vingt mille faits"},{"id":"d2","texte":"Écrit en latin un traité de médecine"}]}]}$ex$::jsonb,
