  ('8fc83035-70b5-53ee-82ab-bad804fd1919'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Une mort qui n’est rien","competence":"manier-langue","situation":"Lucrèce veut délivrer les hommes de la peur de la mort. Analyse sa formule, puis retrouve le vocabulaire de sa physique.","documents":[{"id":"mort","type":"texte","genre":"poeme","titre":"De rerum natura, III, 830","blocs":["Nil igitur mors est ad nos."],"source":"Lucrèce, *De rerum natura* III, 830 (début du vers)"}],"questions":[{"enonce":"Touche le mot latin qui signifie « donc ».","aide":"C’est un connecteur logique, présent dans le cours.","type":"zone","document":"mort","multiple":false},{"enonce":"Touche le sujet du verbe « est ».","aide":"La phrase parle de ce qui n’est « rien » pour nous.","type":"zone","document":"mort","multiple":false},{"enonce":"Quelle traduction convient le mieux à la phrase ?","aide":"*Nil* est un sujet ou un attribut ? Cherche qui est « rien ».","type":"choix","options":[{"id":"a","texte":"La mort n’est donc rien pour nous"},{"id":"b","texte":"Nous ne sommes donc rien pour la mort"},{"id":"c","texte":"La mort vient donc jusqu’à nous"},{"id":"d","texte":"Rien n’est donc mort pour nous"}],"multiple":false},{"enonce":"Associe chaque terme de la physique de Lucrèce à son sens.","aide":"Pense à la physique d’Épicure.","type":"association","gauche":[{"id":"g0","texte":"inane"},{"id":"g1","texte":"semina rerum"},{"id":"g2","texte":"clinamen"},{"id":"g3","texte":"animus"}],"droite":[{"id":"d0","texte":"L’esprit, fait d’atomes"},{"id":"d1","texte":"La légère déviation"},{"id":"d2","texte":"Les atomes"},{"id":"d3","texte":"Le vide"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1"]},"explication":"**Igitur** signifie « donc » : il annonce la conclusion d’un raisonnement."},{"cle":{"type":"zone","ids":["m2"]},"explication":"Le sujet est **mors**, « la mort », au nominatif."},{"cle":{"type":"choix","ids":["a"]},"explication":"« **La mort n’est donc rien pour nous.** » *Mors* est le sujet, *nil* l’attribut, *ad nos* « pour nous »."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g1":"d2","g0":"d3"}},"explication":"**Inane** est le vide, **semina rerum** les atomes, **clinamen** la déviation, **animus** l’esprit, lui aussi fait d’atomes."}]$ex$::jsonb),
  ('8fc83035-70b5-53ee-82ab-bad804fd1919'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux voix face aux dieux","competence":"argumenter","situation":"Lis deux réponses imaginées pour l’exercice : l’une épicurienne, l’autre académicienne. Croise-les avec le tableau de Cicéron pour les attribuer.","documents":[{"id":"voix","type":"texte","genre":"recit","titre":"Débat au Jardin","blocs":["**Lucile** : Les dieux vivent heureux, loin de nous. Prier pour que le vent se lève ne sert à rien.","**Marc** : Je ne sais pas si l’oiseau annonce l’avenir. Je cherche le plus probable, et je suspends mon jugement."],"source":"Dialogue écrit pour l’exercice"},{"id":"mots","type":"tableau","titre":"Religio et superstitio chez Cicéron","colonnes":["Mot","Sens"],"lignes":[["religio","Scrupule, culte réglé des dieux"],["superstitio","Crainte excessive, crédulité"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Laquelle des deux voix est épicurienne ?","aide":"Pour Épicure, les dieux ne s’intéressent pas aux hommes.","type":"choix","options":[{"id":"a","texte":"Aucune des deux, car elles croient aux dieux"},{"id":"b","texte":"Lucile, pour qui les dieux ne s’occupent pas de nous"},{"id":"c","texte":"Marc, pour qui la divination reste incertaine"},{"id":"d","texte":"Les deux, car toutes deux doutent de l’avenir"}],"multiple":false},{"enonce":"Attribue chaque idée à Lucrèce ou à Cicéron.","aide":"L’un est un poète épicurien, l’autre un avocat, augure et académicien.","type":"categories","categories":[{"id":"c0","texte":"Lucrèce"},{"id":"c1","texte":"Cicéron"}],"items":[{"id":"i0","texte":"Mettre en vers la physique d’Épicure"},{"id":"i1","texte":"Distinguer religio et superstitio"},{"id":"i2","texte":"L’âme est faite d’atomes et se disperse"},{"id":"i3","texte":"Les dieux ne s’occupent pas des hommes"},{"id":"i4","texte":"Rapporter le mot de Caton sur les haruspices"},{"id":"i5","texte":"Suspendre son jugement quand on ne sait pas"}]},{"enonce":"Touche le mot que Cicéron réserve à la crainte excessive qui asservit l’esprit.","aide":"Il s’oppose à *religio*.","type":"zone","document":"mots","multiple":false},{"enonce":"Marc, en cherchant « le plus probable », parle comme…","aide":"Quelle école suspend son jugement ?","type":"choix","options":[{"id":"a","texte":"Pline, auteur de l’Histoire naturelle"},{"id":"b","texte":"Augustin, évêque d’Hippone"},{"id":"c","texte":"Cicéron, membre de la Nouvelle Académie"},{"id":"d","texte":"Lucrèce, disciple fidèle d’Épicure"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"**Lucile** est épicurienne : les dieux, heureux, **ne s’occupent pas des hommes**. Marc suspend son jugement, comme la Nouvelle Académie."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1","i5":"c1"}},"explication":"**Lucrèce** : dieux lointains, âme d’atomes, physique d’Épicure en vers. **Cicéron** : suspension du jugement, religio/superstitio, mot de Caton."},{"cle":{"type":"zone","ids":["r1c0"]},"explication":"C’est **superstitio** : la peur excessive, la crédulité."},{"cle":{"type":"choix","ids":["c"]},"explication":"Chercher le probable et suspendre son jugement est la méthode de la **Nouvelle Académie**, celle de **Cicéron**."}]$ex$::jsonb),
