  ('a4d78489-85e8-5176-9e2a-daf3772f8d8d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Il reste Médée","competence":"analyser-texte","situation":"Médée a perdu sa patrie, son époux, ses protections. La nourrice le lui rappelle ; l’héroïne répond en deux mots, restés célèbres.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Médée, acte I","auteur":"D’après Sénèque, *Médée* (v. 166)","blocs":[{"didascalie":"La nourrice rappelle à Médée que tout est perdu."},{"personnage":"La nourrice","replique":"Que te reste-t-il, après tant de malheurs ?"},{"personnage":"Médée","replique":"Medea superest."}],"source":"Réplique de la nourrice adaptée en français ; réponse de Médée citée en latin"}],"questions":[{"enonce":"Touche le verbe de la réponse de Médée.","aide":"C’est un verbe formé de deux parties : *super* et une forme de « être ».","type":"zone","document":"scene","multiple":false},{"enonce":"Complète l’analyse du verbe.","aide":"Le verbe *sum* est au présent, à la 3e personne du singulier.","type":"trous","segments":["« Superest » se décompose en *super* + ",0,"."],"banque":["esse","erat","sunt","est"]},{"enonce":"Range ces mots dans le vocabulaire de la passion ou dans celui de la raison stoïcienne.","aide":"*Furor* est la fureur ; *ratio* est la raison.","type":"categories","categories":[{"id":"c0","texte":"La passion"},{"id":"c1","texte":"La raison stoïcienne"}],"items":[{"id":"i0","texte":"*constantia*"},{"id":"i1","texte":"*ira*"},{"id":"i2","texte":"*sapientia*"},{"id":"i3","texte":"*dolor*"},{"id":"i4","texte":"*furor*"},{"id":"i5","texte":"*ratio*"}]},{"enonce":"Selon la méthode pour lire une tirade de Sénèque, que faut-il repérer en premier ?","aide":"Le héros s’exhorte lui-même au crime.","type":"choix","options":[{"id":"a","texte":"Les noms propres et les dates"},{"id":"b","texte":"Les mots grecs et leur origine"},{"id":"c","texte":"Les impératifs et subjonctifs"},{"id":"d","texte":"Les rimes et les refrains"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m17"]},"explication":"Le verbe est **superest**, de *supersum*, « rester » : « il reste Médée »."},{"cle":{"type":"trous","trous":[["est"]]},"affichage":"est","explication":"**Super + est** : littéralement « il est en plus, il reste »."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c0","i5":"c1"}},"explication":"**Passion** : *furor* (fureur), *ira* (colère), *dolor* (douleur). **Raison stoïcienne** : *ratio* (raison), *sapientia* (sagesse), *constantia* (fermeté)."},{"cle":{"type":"choix","ids":["c"]},"explication":"On repère d’abord les **impératifs et les subjonctifs de souhait** : par eux, le héros s’exhorte au crime."}]$ex$::jsonb),
  ('a4d78489-85e8-5176-9e2a-daf3772f8d8d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La vie est une pièce","competence":"analyser-texte","situation":"Sénèque compare la vie à une pièce de théâtre. Cette image a traversé les siècles : lis la phrase latine, puis replace-la dans son histoire.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettres à Lucilius, 77","blocs":["Quomodo fabula, sic vita : non quam diu, sed quam bene acta sit, refert."],"source":"Sénèque, *Lettres à Lucilius*, 77, 20 (phrase célèbre)"},{"id":"theatre","type":"tableau","titre":"Le theatrum mundi à travers les siècles","colonnes":["Époque","L’œuvre","L’image du théâtre"],"lignes":[["Ier siècle","Sénèque, *Lettres à Lucilius*","Bien jouer son rôle, quelle que soit sa longueur"],["1599","Shakespeare, *Comme il vous plaira*","Le monde entier est un théâtre"],["1635","Calderón, *La vie est un songe*","Le réel et l’illusion se confondent"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche les deux mots qui comparent la vie à une pièce de théâtre.","aide":"Ce sont les deux noms à la fois : l’un dit « pièce », l’autre « vie ».","type":"zone","document":"lettre","multiple":true},{"enonce":"Touche l’adverbe qui dit la qualité du jeu.","aide":"C’est le mot latin d’où vient le français « bien ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’œuvre qui date de l’Antiquité.","aide":"Regarde la colonne « Époque » : une seule ligne donne un siècle après J.-C.","type":"zone","document":"theatre","multiple":false},{"enonce":"Complète la traduction de la phrase de Sénèque.","aide":"*Quam diu* : « combien de temps » ; *quam bene acta sit* : « comme elle a été bien jouée ».","type":"trous","segments":["Il en va de la vie comme d’une ",0," : ce qui compte, ce n’est pas sa ",1,", mais la qualité du ",2,"."],"banque":["jeu","durée","fin","pièce","décor"]},{"enonce":"Pourquoi cette image de la vie comme une pièce est-elle stoïcienne ?","aide":"Pour les stoïciens, on n’est pas maître du destin, mais on l’est de sa conduite.","type":"choix","options":[{"id":"a","texte":"Seule une longue vie permet de bien jouer son rôle"},{"id":"b","texte":"Le sort d’un acteur ne dépend que des spectateurs"},{"id":"c","texte":"On doit fuir le théâtre et la cité pour rester sage"},{"id":"d","texte":"On ne choisit pas son rôle, mais la façon de le jouer"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m1","m3"]},"explication":"**Fabula** (la pièce) et **vita** (la vie) sont mis en parallèle par *quomodo… sic…* : « de même que… ainsi… »."},{"cle":{"type":"zone","ids":["m9"]},"explication":"**Bene** signifie « bien » : ce qui compte, c’est que la pièce soit bien jouée."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"L’œuvre antique est celle de **Sénèque**, au Ier siècle ; les deux autres datent de 1599 et de 1635."},{"cle":{"type":"trous","trous":[["piece"],["duree"],["jeu"]]},"affichage":"pièce · durée · jeu","explication":"**Fabula** : la pièce ; **diu** : longtemps, donc la durée ; **bene acta** : bien jouée, donc la qualité du jeu."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le stoïcien accepte le **rôle que le destin lui donne** et met son exigence dans la façon de le jouer : « non quam diu, sed quam bene »."}]$ex$::jsonb),
  ('1917545c-4cb7-59e5-a3c2-3ee1cafe0a40'::uuid, 1, 1, 5, 20, 3,
