  ('f383dc99-8a45-5edf-ab4b-743fa80757bc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le barbare, c’est moi","competence":"argumenter","situation":"Pour un essai sur le regard porté sur l’étranger, tu confrontes un vers d’Ovide à un tableau des motifs qui rapprochent les deux œuvres.","documents":[{"id":"barbare","type":"texte","genre":"poeme","titre":"Tristes, livre V","blocs":["Barbarus hic ego sum, quia non intellegor ulli."],"source":"Ovide, *Tristes*, V, 10, 37 (vers célèbre)"},{"id":"motifs","type":"tableau","titre":"Trois motifs à confronter","colonnes":["Motif","Chez Ovide","Chez Blixen"],"lignes":[["Le paysage","L’hiver de Tomis sert d’argument","La lumière des collines est un souvenir"],["Le destin","Il accuse un dieu, Auguste, et sa faute","Elle accepte les coups du sort avec fierté"],["L’étranger","Il finit par se dire barbare","Elle voit ses voisins comme des personnes, sans échapper au regard colonial"]],"enteteLignes":true,"source":"D’après le cours"}],"questions":[{"enonce":"Touche le mot par lequel Ovide se désigne lui-même.","aide":"Pour les Romains, c’est celui qui ne parle ni latin ni grec.","type":"zone","document":"barbare","multiple":false},{"enonce":"Touche le verbe qui explique pourquoi Ovide se sent barbare.","aide":"Le verbe est à la forme passive : « je suis… ».","type":"zone","document":"barbare","multiple":false},{"enonce":"Touche la case du tableau qui correspond à ce vers d’Ovide.","aide":"Le vers parle du regard porté sur l’étranger.","type":"zone","document":"motifs","multiple":false},{"enonce":"Quelle affirmation est la plus juste sur le regard de Blixen ?","aide":"Relis la dernière ligne du tableau : un essai gagne à nuancer.","type":"choix","options":[{"id":"a","texte":"Elle les juge comme Ovide juge les Gètes"},{"id":"b","texte":"Elle les décrit avec un regard totalement neutre"},{"id":"c","texte":"Elle ne parle jamais de ses voisins africains"},{"id":"d","texte":"Elle décrit des personnes, sans échapper à son époque"}],"multiple":false},{"enonce":"Range chaque trait du côté d’Ovide, de Blixen ou des deux.","aide":"Un trait qui vaut pour les deux œuvres va dans la troisième colonne.","type":"categories","categories":[{"id":"c0","texte":"Ovide"},{"id":"c1","texte":"Blixen"},{"id":"c2","texte":"Les deux"}],"items":[{"id":"i0","texte":"S’adresse d’abord à Auguste"},{"id":"i1","texte":"Écrit parce qu’il est loin de chez lui"},{"id":"i2","texte":"Regrette un lieu aimé"},{"id":"i3","texte":"Écrit depuis le Danemark, après un échec"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m0"]},"explication":"**Barbarus** : à Tomis, c’est Ovide qui est le barbare, puisque personne ne le comprend."},{"cle":{"type":"zone","ids":["m6"]},"explication":"**Intellegor** : « je suis compris ». Comme *non intellegor ulli*, « personne ne me comprend », il devient le barbare des autres."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"Le vers correspond à la case **« Il finit par se dire barbare »**, sur la ligne de l’étranger."},{"cle":{"type":"choix","ids":["d"]},"explication":"Blixen voit ses voisins comme des **personnes**, mais **sans échapper** tout à fait au regard du colon de son temps : il faut le dire avec nuance."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c2","i3":"c1"}},"explication":"Seul **Ovide** plaide auprès d’Auguste ; seule **Blixen** écrit du Danemark après son échec ; **les deux** écrivent loin de chez eux et regrettent un lieu aimé."}]$ex$::jsonb),
